<?php

declare(strict_types=1);
require_once __DIR__ . '/auth_check.php';
require_once __DIR__ . '/bootstrap.php';

$pdo = app_database();
function webOrderEscape(mixed $value): string { return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$statuses = ['nouvelle' => 'Nouvelle', 'contactee' => 'Client contacté', 'confirmee' => 'Confirmée', 'preparation' => 'En préparation', 'livraison' => 'En livraison', 'terminee' => 'Terminée', 'annulee' => 'Annulée'];
if (!isset($_SESSION['web_order_csrf'])) $_SESSION['web_order_csrf'] = bin2hex(random_bytes(24));

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals((string) $_SESSION['web_order_csrf'], (string) ($_POST['csrf_token'] ?? ''))) {
        header('Location: commandes_boutique.php?error=session'); exit;
    }
    $orderId = (int) ($_POST['order_id'] ?? 0); $status = (string) ($_POST['statut'] ?? '');
    if ($orderId > 0 && isset($statuses[$status])) {
        $statement = $pdo->prepare('UPDATE commandes_boutique SET statut=:statut WHERE id=:id');
        $statement->execute(['statut' => $status, 'id' => $orderId]);
        header('Location: commandes_boutique.php?updated=1&focus=' . $orderId); exit;
    }
}

$where = ['1=1']; $parameters = [];
$query = trim((string) ($_GET['q'] ?? ''));
if ($query !== '') { $where[] = '(co.reference_commande LIKE :q OR co.nom_contact LIKE :q OR co.entreprise LIKE :q OR co.email LIKE :q OR co.telephone LIKE :q OR co.commune LIKE :q)'; $parameters['q'] = '%' . $query . '%'; }
$filterStatus = (string) ($_GET['statut'] ?? '');
if (isset($statuses[$filterStatus])) { $where[] = 'co.statut=:statut'; $parameters['statut'] = $filterStatus; }
if (($_GET['date_from'] ?? '') !== '') { $where[] = 'DATE(co.created_at)>=:date_from'; $parameters['date_from'] = $_GET['date_from']; }
if (($_GET['date_to'] ?? '') !== '') { $where[] = 'DATE(co.created_at)<=:date_to'; $parameters['date_to'] = $_GET['date_to']; }
$statement = $pdo->prepare('SELECT co.*,(SELECT SUM(l.quantite) FROM commande_boutique_ligne l WHERE l.commande_id=co.id) articles FROM commandes_boutique co WHERE ' . implode(' AND ', $where) . ' ORDER BY co.created_at DESC,co.id DESC');
$statement->execute($parameters); $orders = $statement->fetchAll(PDO::FETCH_ASSOC);
$lines = [];
if ($orders) { $ids = array_column($orders, 'id'); $marks = implode(',', array_fill(0, count($ids), '?')); $lineStatement = $pdo->prepare("SELECT * FROM commande_boutique_ligne WHERE commande_id IN ($marks) ORDER BY id"); $lineStatement->execute($ids); foreach ($lineStatement->fetchAll(PDO::FETCH_ASSOC) as $line) $lines[(int) $line['commande_id']][] = $line; }
$metrics = array_fill_keys(array_keys($statuses), 0); $metrics['total'] = 0;
foreach ($pdo->query('SELECT statut,COUNT(*) total FROM commandes_boutique GROUP BY statut')->fetchAll(PDO::FETCH_ASSOC) as $metric) { $metrics[$metric['statut']] = (int) $metric['total']; $metrics['total'] += (int) $metric['total']; }
?>
