9eb}.web-order-body{display:grid;grid-template-columns:1fr 1.15fr .85fr;gap:22px;padding:20px}.info-block h3{margin:0 0 11px;color:var(--brand-primary);font:800 .77rem var(--brand-font-heading);text-transform:uppercase}.info-block p{margin:5px 0;color:var(--brand-text-muted);font-size:.76rem}.info-block p i{width:18px;color:var(--brand-primary)}.order-products{display:grid;gap:7px}.order-product{display:grid;grid-template-columns:1fr auto;gap:10px;padding:9px 11px;background:#f7f7fa;border-radius:9px;font-size:.72rem}.order-product strong{display:block}.order-product small{color:var(--brand-text-muted)}.web-order-total{margin-top:10px;text-align:right;color:var(--brand-primary);font-weight:900}.status-form{display:grid;gap:9px}.status-form .btn{width:100%}.empty-orders{padding:70px;text-align:center;color:var(--brand-text-muted);background:#fff;border-radius:18px}@media(max-width:900px){.web-order-kpis{grid-template-columns:1fr 1fr}.web-order-body{grid-template-columns:1fr 1fr}.web-order-body>.info-block:last-child{grid-column:1/-1}}@media(max-width:600px){.web-orders-hero{align-items:flex-start;flex-direction:column;padding:23px}.web-order-kpis{grid-template-columns:1fr 1fr}.web-order-body{grid-template-columns:1fr}.web-order-body>.info-block:last-child{grid-column:auto}.web-order-head{align-items:flex-start;flex-direction:column}.web-order-filters .row>*{margin-bottom:8px}}
</style></head><body class="module-page web-orders-page"><?php include __DIR__ . '/partials/navbar.php'; ?><main class="container"><section class="web-orders-hero"><div><div class="small fw-bold text-warning">VENTES EN LIGNE</div><h1>Commandes de la boutique</h1><p>Traitez les demandes reçues depuis la boutique publique et suivez leur livraison.</p></div><a class="btn" href="boutique_publique.php" target="_blank"><i class="fa-solid fa-arrow-up-right-from-square me-2"></i>Voir la boutique publique</a></section>
<?php if(isset($_GET['updated'])):?><div class="alert alert-success">Le statut de la commande a été mis à jour.</div><?php endif;?>
<section class="web-order-kpis"><div class="web-order-kpi"><i class="fa-solid fa-cart-shopping"></i><small>Total</small><strong><?= (int)$metrics['total'] ?></strong></div><div class="web-order-kpi"><i class="fa-solid fa-bell"></i><small>Nouvelles</small><strong><?= (int)$metrics['nouvelle'] ?></strong></div><div class="web-order-kpi"><i class="fa-solid fa-box"></i><small>En préparation</small><strong><?= (int)$metrics['preparation'] ?></strong></div><div class="web-order-kpi"><i class="fa-solid fa-circle-check"></i><small>Terminées</small><strong><?= (int)$metrics['terminee'] ?></strong></div></section>
<form class="web-order-filters" method="get"><div class="row g-2 align-items-end"><div class="col-lg-4"><label class="form-label">Recherche</label><input class="form-control" name="q" value="<?= webOrderEscape($_GET['q']??'') ?>" placeholder="Référence, client, téléphone…"></div><div class="col-lg-2 col-md-3"><label class="form-label">Du</label><input class="form-control" type="date" name="date_from" value="<?= webOrderEscape($_GET['date_from']??'') ?>"></div><div class="col-lg-2 col-md-3"><label class="form-label">Au</label><input class="form-control" type="date" name="date_to" value="<?= webOrderEscape($_GET['date_to']??'') ?>"></div><div class="col-lg-2 col-md-3"><label class="form-label">Statut</label><select class="form-select" name="statut"><option value="">Tous</option><?php foreach($statuses as$value=>$label):?><option value="<?=$value?>" <?=($_GET['statut']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-lg-2 col-md-3"><button class="btn btn-primary w-100"><i class="fa-solid fa-filter"></i> Filtrer</button></div></div></form>
<section class="web-order-list"><?php if(!$orders):?><div class="empty-orders"><i class="fa-regular fa-folder-open fa-2x d-block mb-3"></i>Aucune commande ne correspond aux critères.</div><?php endif;?><?php foreach($orders as$order):?><article class="web-order-card <?= (int)($_GET['focus']??0)===(int)$order['id']?'focus':'' ?>"><header class="web-order-head"><div><h2><?=webOrderEscape($order['reference_commande'])?></h2><p>Reçue le <?=webOrderEscape(date('d/m/Y à H:i',strtotime($order['created_at'])))?> · <?= (int)$order['articles'] ?> article(s)</p></div><span class="web-status <?=webOrderEscape($order['statut'])?>"><?=webOrderEscape($statuses[$order['statut']]??$order['statut'])?></span></header><div class="web-order-body"><div class="info-block"><h3>Client</h3><p><i class="fa-solid fa-user"></i><strong><?=webOrderEscape($order['nom_contact'])?></strong></p><?php if($order['entreprise']):?><p><i class="fa-solid fa-building"></i><?=webOrderEscape($order['entreprise'])?></p><?php endif?><p><i class="fa-solid fa-phone"></i><a href="tel:<?=webOrderEscape($order['telephone'])?>"><?=webOrderEscape($order['telephone'])?></a></p><p><i class="fa-solid fa-envelope"></i><a href="mailto:<?=webOrderEscape($order['email'])?>"><?=webOrderEscape($order['email'])?></a></p><h3 class="mt-3">Livraison</h3><p><i class="fa-solid fa-location-dot"></i><?=webOrderEscape($order['adresse_livraison'])?>, <?=webOrderEscape($order['commune'])?>, <?=webOrderEscape($order['ville'])?></p><?php if($order['indications']):?><p><i class="fa-solid fa-circle-info"></i><?=webOrderEscape($order['indications'])?></p><?php endif?></div><div class="info-block"><h3>Articles commandés</h3><div class="order-products"><?php foreach($lines[(int)$order['id']]??[] as$line):?><div class="order-product"><div><strong><?=webOrderEscape($line['designation'])?></strong><small><?=number_format((float)$line['prix_unitaire'],0,',',' ')?> FCFA × <?= (int)$line['quantite'] ?></small></div><strong><?=number_format((float)$line['total_ligne'],0,',',' ')?> F</strong></div><?php endforeach?></div><div class="web-order-total">Total estimé : <?=number_format((float)$order['total_estime'],0,',',' ')?> FCFA HT</div></div><div class="info-block"><h3>Traitement</h3><form class="status-form" method="post"><input type="hidden" name="csrf_token" value="<?=webOrderEscape($_SESSION['web_order_csrf'])?>"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><select class="form-select" name="statut"><?php foreach($statuses as$value=>$label):?><option value="<?=$value?>" <?=$order['statut']===$value?'selected':''?>><?=$label?></option><?php endforeach?></select><button class="btn btn-primary"><i class="fa-solid fa-check me-1"></i>Mettre à jour</button><a class="btn btn-outline-primary" href="tel:<?=webOrderEscape($order['telephone'])?>"><i class="fa-solid fa-phone me-1"></i>Appeler le client</a><a class="btn btn-outline-primary" href="mailto:<?=webOrderEscape($order['email'])?>?subject=Commande%20<?=rawurlencode($order['reference_commande'])?>"><i class="fa-solid fa-envelope me-1"></i>Envoyer un e-mail</a></form></div></div></article><?php endforeach?></section></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script></body></html>
